sysauto_script.script:
function copyAssessment(oldItemGR, newCaseSysId) {
    //copy records
    var addHist = '';

    addHist += 'HR Task: ' + oldItemGR.hr_task.number + '\n';
    addHist += 'Recommended Action: ' + oldItemGR.recommended_action + '\n';
    addHist += 'Start Date for Implementing Control Measures: ' + oldItemGR.start_date.getDisplayValue() + '\n';
    addHist += 'Is there a training Component Involved? ' + oldItemGR.training + '\n\n';

    var newItem = new GlideRecord('x_hccc_hoc_ohs_hazard_investigation_and_risk_assessment');

    newItem.initialize();
    newItem.hira_case = newCaseSysId;
    newItem.state = '100';
    newItem.work_task_description = oldItemGR.work_task_description;
    newItem.frequency = oldItemGR.freqency;
    newItem.hazard_category = oldItemGR.hazard_category;
    newItem.hazard_subcategory = oldItemGR.hazard_subcategory;
    newItem.hazard_description = oldItemGR.hazard_description;
    newItem.consequence = oldItemGR.consequence;
    newItem.regulatory_reference = oldItemGR.regulatory_reference;
    newItem.controls_present = oldItemGR.controls_present;
    newItem.likelihood = oldItemGR.likelihood;
    newItem.severity = oldItemGR.severity;
    /*   Commented because the action history should store the previous recommended actions.
    newItem.recommended_action = oldItem.recommended_action;
    newItem.actions_taken_by_manager = oldItem.actions_taken_by_manager;
    newItem.start_date = oldItem.start_date;
    newItem.training = oldItem.training;
    newItem.comments = oldItem.comments;		
    */
    newItem.action_history = addHist;
    newItem.insert();

    //Set old items = "archived"
    oldItemGR.state = 300;
    oldItemGR.active = false;
    oldItemGR.update();

    return newItem;
}

function copyChildAssessments(oldCaseSysId, newCaseSysId) {
    var oldItem = new GlideRecord('x_hccc_hoc_ohs_hazard_investigation_and_risk_assessment');

    oldItem.addQuery('hira_case', oldCaseSysId);
    oldItem.query();

    while (oldItem.next()) {
        copyAssessment(oldItem, newCaseSysId);
    }
}

function copyCase(oldCaseGR) {
    //Get person this position reports to from Position data
    var grJob = new GlideRecord('sn_hr_core_job');
    var mgr = '';

    grJob.addQuery('position', oldCaseGR.position.u_parent_position);
    grJob.query();

    if (grJob.next()) {
        mgr = grJob.user;
    } else {
        mgr = '';
    }

    //copy parent case

    var newCase = new GlideRecord('x_hccc_hoc_ohs_investigation_case');

    newCase.initialize();
    newCase.hr_service = '3fb664a08754515050d2eca73cbb35f1';
    newCase.position = oldCaseGR.position;
    newCase.service_area = oldCaseGR.service_area;
    newCase.manager_name = mgr; //set manager field to Position's Report's To person
    newCase.opened_for = mgr;
    newCase.assignment_group = '44f382bd1be901109fde86acdd4bcba5'; // OHS Representatives
    newCase.state = 1;
    newCase.insert();

    oldCaseGR.active = false;
    oldCaseGR.update();

    //copy child assessments (loop)
    copyChildAssessments(oldCaseGR.sys_id, newCase.sys_id);

    return newCase;
}

function getReviewDueDateIn6Months() {
    var dtReview = new GlideDateTime();

    dtReview.addMonthsLocalTime(-6);
    return dtReview.getLocalDate();
}

var dueIn6Months = getReviewDueDateIn6Months();
var qryDueIn6Months =
    'review_dueON' + dueIn6Months +
    '@javascript:gs.dateGenerate("' + dueIn6Months +
    '","start")@javascript:gs.dateGenerate("' + dueIn6Months + '","end")';

var oldCase = new GlideRecord('x_hccc_hoc_ohs_investigation_case');

oldCase.addActiveQuery();
oldCase.addQuery('hr_service', '3fb664a08754515050d2eca73cbb35f1');
oldCase.addEncodedQuery(qryDueIn6Months);
oldCase.query();

while (oldCase.next()) {
    var newCase = copyCase(oldCase);

    gs.eventQueue('x_hccc_hoc_ohs.hira.due_to_review_manager', newCase, gs.getUserName(), gs.getUserID()); //trigger email to manager.
}
